INSERT INTO metric_definitions (metric_key, name, category_key, definition, executive_meaning, unit, data_type, directionality, board_relevance, trend_relevance, risk_relevance, visualization_json, story_tags_json, related_metric_keys_json, caveats_json, version, active) VALUES
('total_security_incidents', 'Total security incidents', 'incidents_threat', 'Total number of confirmed security incidents recorded in the reporting period.', 'Indicates overall threat pressure and reporting maturity; raw volume alone does not measure security posture.', 'count', 'count', 'context_dependent', 4, 4, 3, '["kpi","bar","line"]', '["threat_pressure","incidents"]', '["material_security_incidents","critical_security_incidents","mttd"]', '["Absolute counts are influenced by detection, reporting maturity and the size of the environment.","Interpretation is context-dependent; a change is not automatically good or bad."]', '1.0.0', 1),
('material_security_incidents', 'Material security incidents', 'incidents_threat', 'Incidents that met the organisation''s materiality criteria (financial, operational or regulatory impact).', 'The clearest Board-relevant measure of realised business impact from security events.', 'count', 'count', 'lower_is_better', 5, 4, 5, '["kpi","bar","line"]', '["business_impact","incidents"]', '["total_security_incidents","records_affected","cyber_downtime"]', '["Absolute counts are influenced by detection, reporting maturity and the size of the environment.","Materiality criteria differ by organisation; state the definition used."]', '1.0.0', 1),
('critical_security_incidents', 'Critical security incidents', 'incidents_threat', 'Incidents classified as critical under the organisation''s severity methodology.', 'Signals severity concentration and the potential for significant disruption or loss.', 'count', 'count', 'lower_is_better', 5, 4, 5, '["kpi","bar","line"]', '["severity","incidents"]', '["material_security_incidents","mttr","critical_service_availability"]', '["Absolute counts are influenced by detection, reporting maturity and the size of the environment."]', '1.0.0', 1),
('high_severity_incidents', 'High-severity security incidents', 'incidents_threat', 'Incidents classified as high severity under the organisation''s severity methodology.', 'Indicates the volume of serious events short of the critical threshold.', 'count', 'count', 'lower_is_better', 4, 4, 4, '["kpi","bar","line"]', '["severity","incidents"]', '["critical_security_incidents","high_severity_alert_volume"]', '["Absolute counts are influenced by detection, reporting maturity and the size of the environment."]', '1.0.0', 1),
('ransomware_incidents', 'Ransomware incidents', 'incidents_threat', 'Number of confirmed ransomware-related incidents in the period.', 'Board-critical due to potential for severe operational, financial and reputational harm.', 'count', 'count', 'lower_is_better', 5, 3, 5, '["kpi","bar","line"]', '["ransomware","threat_pressure"]', '["immutable_backup_coverage","restore_test_success_rate","material_security_incidents"]', '["Absolute counts are influenced by detection, reporting maturity and the size of the environment."]', '1.0.0', 1),
('phishing_incidents', 'Phishing incidents', 'incidents_threat', 'Number of confirmed phishing incidents affecting users or systems.', 'Reflects the effectiveness of email controls and human-risk mitigation.', 'count', 'count', 'lower_is_better', 3, 3, 3, '["kpi","bar","line"]', '["phishing","human_risk"]', '["phishing_failure_rate","awareness_completion","account_compromise_incidents"]', '["Absolute counts are influenced by detection, reporting maturity and the size of the environment."]', '1.0.0', 1),
