('account_compromise_incidents', 'Account compromise incidents', 'incidents_threat', 'Number of confirmed incidents where a user or service account was compromised.', 'Signals the effectiveness of identity and access controls.', 'count', 'count', 'lower_is_better', 4, 3, 4, '["kpi","bar","line"]', '["identity","incidents"]', '["mfa_coverage","identity_incidents","privileged_access_violations"]', '["Absolute counts are influenced by detection, reporting maturity and the size of the environment."]', '1.0.0', 1),
('insider_incidents', 'Insider-related security incidents', 'incidents_threat', 'Confirmed incidents involving malicious or negligent insider activity.', 'Indicates insider-risk exposure and the effectiveness of data and access monitoring.', 'count', 'count', 'lower_is_better', 4, 3, 4, '["kpi","bar","line"]', '["insider_risk","data"]', '["data_access_anomalies","excessive_data_access_privileges","dlp_incidents"]', '["Absolute counts are influenced by detection, reporting maturity and the size of the environment."]', '1.0.0', 1),
